mapper.select:
SELECT workspace_id, user_id, provider, enabled, calendar_enabled,
       mail_inbox_enabled, mail_sent_enabled, backfill_days, include_bodies,
       admission_mode, excluded_people_json, excluded_conversations_json,
       version, created_at, updated_at
FROM provider_capture_user_policy
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND provider = #{provider}

SELECT user_id
FROM provider_capture_user_policy
WHERE workspace_id = #{workspaceId}
  AND provider = #{provider}
  AND enabled = TRUE
ORDER BY user_id

mapper.update:
UPDATE provider_capture_sync_state
SET status = 'queued', next_attempt_at = UTC_TIMESTAMP(6), error_code = NULL
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND provider = #{provider}
  AND status NOT IN ('backfilling', 'syncing', 'purging')

UPDATE provider_capture_sync_state
SET status = 'paused',
    next_attempt_at = NULL,
    error_code = 'policy_disabled',
    lease_owner = NULL,
    lease_until = NULL
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND provider = #{provider}

UPDATE provider_capture_sync_state
SET status = 'idle',
    next_attempt_at = NULL,
    error_code = NULL,
    lease_owner = NULL,
    lease_until = NULL
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND provider = #{provider}
  AND status NOT IN ('backfilling', 'syncing', 'purging')

UPDATE provider_capture_sync_state
SET lease_until = #{until}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND lease_owner = #{owner}
  AND lease_until >= #{now}

mapper.select:
SELECT id, workspace_id, user_id, provider, stream, provider_source_id,
       provider_conversation_id,
       source_key_hash, source_version, payload_hash, interaction_type, subject,
       body, occurred_at, ended_at, visibility, admission_status,
       admitted_fields_json, material_exclusions_json, policy_version, version,
       last_seen_reconciliation_marker, tombstoned_at, captured_at, updated_at
FROM provider_captured_interaction
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND provider = #{provider}
  AND source_key_hash = #{sourceKeyHash}

SELECT id, workspace_id, user_id, provider, stream, provider_source_id,
       provider_conversation_id,
       source_key_hash, source_version, payload_hash, interaction_type, subject,
       body, occurred_at, ended_at, visibility, admission_status,
       admitted_fields_json, material_exclusions_json, policy_version, version,
       last_seen_reconciliation_marker, tombstoned_at, captured_at, updated_at
FROM provider_captured_interaction
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND provider = #{provider}
  AND id = #{id}
FOR UPDATE

mapper.update:
UPDATE provider_captured_interaction
SET source_version = #{sourceVersion},
    provider_conversation_id = #{providerConversationId},
    payload_hash = #{payloadHash},
    subject = #{subject},
    body = #{body},
    occurred_at = #{occurredAt},
    ended_at = #{endedAt},
    visibility = #{visibility},
    admission_status = #{admissionStatus},
    admitted_fields_json = #{admittedFieldsJson},
    material_exclusions_json = #{materialExclusionsJson},
    policy_version = #{policyVersion},
    version = version + 1,
    last_seen_reconciliation_marker = #{lastSeenReconciliationMarker},
    tombstoned_at = #{tombstonedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND (
    payload_hash <> #{payloadHash}
    OR admission_status <> #{admissionStatus}
    OR NOT (
      last_seen_reconciliation_marker
      <=> #{lastSeenReconciliationMarker}
    )
  )

UPDATE provider_captured_interaction
SET last_seen_reconciliation_marker = #{marker},
    source_version = #{sourceVersion},
    captured_at = UTC_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND id = #{id}

mapper.delete:
DELETE activity
FROM activity
JOIN provider_activity_projection projection
  ON projection.workspace_id = activity.workspace_id
  AND projection.activity_id = activity.id
JOIN provider_captured_interaction interaction
  ON interaction.workspace_id = projection.workspace_id
  AND interaction.id = projection.interaction_id
WHERE interaction.workspace_id = #{workspaceId}
  AND interaction.user_id = #{userId}
  AND interaction.provider = #{provider}
  AND interaction.stream = #{stream}
  AND NOT (
    interaction.last_seen_reconciliation_marker <=> #{marker}
  )

DELETE participant
FROM provider_captured_participant participant
JOIN provider_captured_interaction interaction
  ON interaction.workspace_id = participant.workspace_id
  AND interaction.id = participant.interaction_id
WHERE interaction.workspace_id = #{workspaceId}
  AND interaction.user_id = #{userId}
  AND interaction.provider = #{provider}
  AND interaction.stream = #{stream}
  AND NOT (
    interaction.last_seen_reconciliation_marker <=> #{marker}
  )

mapper.update:
UPDATE provider_captured_interaction
SET subject = NULL,
    body = NULL,
    admission_status = 'withdrawn',
    admitted_fields_json = JSON_ARRAY(),
    material_exclusions_json = JSON_ARRAY('source_absent'),
    tombstoned_at = UTC_TIMESTAMP(6),
    version = version + 1
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND provider = #{provider}
  AND stream = #{stream}
  AND admission_status <> 'withdrawn'
  AND NOT (
    last_seen_reconciliation_marker <=> #{marker}
  )

mapper.select:
SELECT DISTINCT participant.person_id
FROM provider_captured_interaction interaction
JOIN provider_captured_participant participant
  ON participant.workspace_id = interaction.workspace_id
  AND participant.interaction_id = interaction.id
WHERE interaction.workspace_id = #{workspaceId}
  AND interaction.user_id = #{userId}
  AND interaction.provider = #{provider}
  AND interaction.stream = #{stream}
  AND interaction.last_seen_reconciliation_marker = #{marker}
  AND participant.match_state = 'matched'
  AND participant.person_id IS NOT NULL
ORDER BY participant.person_id

SELECT DISTINCT projection.activity_id
FROM provider_captured_interaction interaction
JOIN provider_activity_projection projection
  ON projection.workspace_id = interaction.workspace_id
  AND projection.interaction_id = interaction.id
WHERE interaction.workspace_id = #{workspaceId}
  AND interaction.user_id = #{userId}
  AND interaction.provider = #{provider}
  AND interaction.stream = #{stream}
  AND interaction.last_seen_reconciliation_marker = #{marker}
ORDER BY projection.activity_id

SELECT DISTINCT person_id FROM provider_captured_participant WHERE workspace_id = #{workspaceId} AND interaction_id IN
#{id}
AND match_state = 'matched' AND person_id IS NOT NULL ORDER BY person_id

SELECT DISTINCT activity_id
FROM provider_activity_projection
WHERE workspace_id = #{workspaceId}
  AND interaction_id IN

    #{id}

ORDER BY activity_id

SELECT id
FROM provider_captured_interaction
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND provider = #{provider}
  AND stream = #{stream}
  AND (
    last_seen_reconciliation_marker IS NULL
    OR last_seen_reconciliation_marker <> #{marker}
  )
  AND admission_status <> 'withdrawn'
ORDER BY id

SELECT COUNT(*)
FROM provider_captured_participant p
JOIN provider_captured_interaction i
  ON i.workspace_id = p.workspace_id AND i.id = p.interaction_id
WHERE p.workspace_id = #{workspaceId}
  AND i.user_id = #{userId}
  AND i.provider = #{provider}
  AND i.admission_status IN ('held', 'admitted')
  AND p.match_state IN ('unmatched', 'ambiguous')

SELECT p.id, p.workspace_id, p.interaction_id, p.participant_role, p.display_name,
       p.email, p.normalized_email, p.person_id, p.match_state, p.held_reason,
       p.version, p.created_at, p.updated_at, i.provider, i.stream,
       i.interaction_type, i.subject, i.occurred_at, i.version AS interaction_version
FROM provider_captured_participant p
JOIN provider_captured_interaction i
  ON i.workspace_id = p.workspace_id AND i.id = p.interaction_id
WHERE p.workspace_id = #{workspaceId}
  AND i.user_id = #{userId}
  AND i.provider = #{provider}
  AND p.id = #{id}
FOR UPDATE

SELECT p.id, p.workspace_id, p.interaction_id, p.participant_role, p.display_name,
       p.email, p.normalized_email, p.person_id, p.match_state, p.held_reason,
       p.version, p.created_at, p.updated_at, i.provider, i.stream,
       i.interaction_type, i.subject, i.occurred_at,
       i.version AS interaction_version
FROM provider_captured_participant p
JOIN provider_captured_interaction i
  ON i.workspace_id = p.workspace_id AND i.id = p.interaction_id
WHERE p.workspace_id = #{workspaceId}
  AND i.user_id = #{userId}
  AND i.provider = #{provider}
  AND i.admission_status IN ('held', 'admitted')
  AND p.id = #{id}

mapper.update:
UPDATE provider_captured_participant
SET match_state = #{matchState},
    person_id = #{personId},
    held_reason = NULL,
    version = version + 1
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND version = #{expectedVersion}
  AND match_state IN ('unmatched', 'ambiguous')

mapper.insert:
INSERT INTO provider_participant_decision (
  workspace_id, user_id, provider, normalized_email, decision, person_id
) VALUES (
  #{workspaceId}, #{userId}, #{provider}, #{normalizedEmail}, #{decision}, #{personId}
)
ON DUPLICATE KEY UPDATE decision = VALUES(decision), person_id = VALUES(person_id)

mapper.select:
SELECT d.person_id
FROM provider_participant_decision d
WHERE d.workspace_id = #{workspaceId}
  AND d.user_id = #{userId}
  AND d.provider = #{provider}
  AND d.normalized_email = #{normalizedEmail}
  AND d.decision = 'attach'

SELECT EXISTS(
  SELECT 1 FROM provider_participant_decision
  WHERE workspace_id = #{workspaceId}
    AND user_id = #{userId}
    AND provider = #{provider}
    AND normalized_email = #{normalizedEmail}
    AND decision = 'ignore'
)

SELECT EXISTS(
  SELECT 1
  FROM person
  WHERE workspace_id = #{workspaceId}
    AND id = #{personId}
    AND (suspended_at IS NOT NULL OR provision_ceased_at IS NOT NULL)
)

mapper.delete:
DELETE activity FROM activity JOIN provider_activity_projection projection ON projection.workspace_id = activity.workspace_id AND projection.activity_id = activity.id JOIN provider_captured_participant participant ON participant.workspace_id = projection.workspace_id AND participant.id = projection.participant_id WHERE projection.workspace_id = #{workspaceId} AND projection.interaction_id = #{interactionId}
AND participant.person_id NOT IN
#{personId}
AND TRUE

DELETE activity
FROM activity
JOIN provider_activity_projection projection
  ON projection.workspace_id = activity.workspace_id
  AND projection.activity_id = activity.id
JOIN provider_captured_interaction interaction
  ON interaction.workspace_id = projection.workspace_id
  AND interaction.id = projection.interaction_id
WHERE interaction.workspace_id = #{workspaceId}
  AND interaction.user_id = #{userId}
  AND interaction.provider = #{provider}
  AND interaction.stream = #{stream}
  AND (
    (
      interaction.interaction_type = 'meeting'
      AND COALESCE(interaction.ended_at, interaction.occurred_at) <= #{before}
    )
    OR (
      interaction.interaction_type = 'email'
      AND interaction.occurred_at < #{before}
    )
  )

DELETE FROM provider_captured_interaction
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND provider = #{provider}
  AND stream = #{stream}
  AND (
    (
      interaction_type = 'meeting'
      AND COALESCE(ended_at, occurred_at) <= #{before}
    )
    OR (
      interaction_type = 'email'
      AND occurred_at < #{before}
    )
  )

mapper.insert:
INSERT IGNORE INTO provider_activity_projection (
  workspace_id, interaction_id, participant_id, activity_id
) VALUES (
  #{workspaceId}, #{interactionId}, #{participantId}, #{activityId}
)

mapper.update:
UPDATE provider_captured_interaction
SET admission_status = 'admitted', version = version + 1
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND version = #{expectedVersion}
  AND admission_status = 'held'

UPDATE provider_captured_interaction
SET admission_status = 'ignored', version = version + 1
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND version = #{expectedVersion}
  AND admission_status = 'held'

UPDATE provider_capture_workspace_policy
SET updated_by_user_id = NULL
WHERE workspace_id = #{workspaceId}
  AND updated_by_user_id = #{userId}

UPDATE provider_capture_workspace_policy
SET updated_by_user_id = NULL
WHERE updated_by_user_id = #{userId}

mapper.delete:
DELETE a
FROM activity a
JOIN provider_activity_projection projection
  ON projection.workspace_id = a.workspace_id AND projection.activity_id = a.id
JOIN provider_captured_interaction interaction
  ON interaction.workspace_id = projection.workspace_id
  AND interaction.id = projection.interaction_id
WHERE a.workspace_id = #{workspaceId}
  AND interaction.user_id = #{userId}
  AND interaction.provider = #{provider}

DELETE FROM provider_captured_interaction
WHERE user_id = #{userId}
  AND provider = #{provider}

DELETE FROM provider_capture_sync_state
WHERE user_id = #{userId}
  AND provider = #{provider}

DELETE FROM provider_capture_user_policy
WHERE user_id = #{userId}
  AND provider = #{provider}

DELETE FROM provider_participant_decision
WHERE user_id = #{userId}
  AND provider = #{provider}
